#include <iostream>

int main() {
    int count = 1;
    int& r = count; // r is an alias for count

    std::cout << "count: " << count << ", r: " << r << "\n";

    r++; // Modifying r modifies count
    std::cout << "count: " << count << ", r: " << r << "\n";

    count = 10; // Modifying count modifies r
    std::cout << "count: " << count << ", r: " << r << "\n";

    return 0;
}

#include <iostream>

// Swaps two integers in place using pass-by-reference
void swap(int& n1, int& n2) {
    int temp = n1;
    n1 = n2;
    n2 = temp;
}

// Increments an integer in place using pass-by-reference
void increment(int& n) {
    n++;
}

int main() {
    int num1 = 1;
    int num2 = 2;

    std::cout << "Before swap: num1 = " << num1 << ", num2 = " << num2 << "\n";
    swap(num1, num2);
    std::cout << "After swap: num1 = " << num1 << ", num2 = " << num2 << "\n";

    increment(num1);
    std::cout << "After increment: num1 = " << num1 << "\n";

    return 0;
}
